class TaskList:
    def __init__(self):
        self.tasks = []

    def add(self, title):
        self.tasks.append({"title": title, "done": False})
        print(f"أضفت: {title}")

    def complete(self, index):
        if 0 <= index < len(self.tasks):
            self.tasks[index]["done"] = True
            print(f"خلصت: {self.tasks[index]['title']}")
        else:
            print("رقم غير موجود")

    def remove(self, index):
        if 0 <= index < len(self.tasks):
            removed = self.tasks.pop(index)
            print(f"حذفت: {removed['title']}")
        else:
            print("رقم غير موجود")

    def show(self):
        if not self.tasks:
            print("ما فيه مهام")
            return
        for i, t in enumerate(self.tasks):
            mark = "✓" if t["done"] else " "
            print(f"[{mark}] {i}: {t['title']}")


if __name__ == "__main__":
    tl = TaskList()
    tl.add("اشتري خبز")
    tl.add("اتصل بأحمد")
    tl.add("ذاكر بايثون")
    tl.show()
    tl.complete(1)
    tl.show()
    tl.remove(0)
    tl.show()
```

