import math


class Rectangle:
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

    def perimeter(self):
        return 2 * (self.width + self.height)


class Circle:
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return math.pi * self.radius ** 2

    def perimeter(self):
        return 2 * math.pi * self.radius


r = Rectangle(4, 6)
print("مستطيل - المساحة:", r.area(), "المحيط:", r.perimeter())

c = Circle(3)
print("دائرة - المساحة:", round(c.area(), 2), "المحيط:", round(c.perimeter(), 2))
```

