  <input id="b" type="number" placeholder="الرقم الثاني">
  <div style="margin-top:15px">
    <button onclick="calc('+')">+</button>
    <button onclick="calc('-')">-</button>
    <button onclick="calc('*')">×</button>
    <button onclick="calc('/')">÷</button>
  </div>
  <div id="result"></div>
<script>
function calc(op) {
  const a = parseFloat(document.getElementById('a').value);
  const b = parseFloat(document.getElementById('b').value);
  let r;
  if (op === '+') r = a + b;
  else if (op === '-') r = a - b;
  else if (op === '*') r = a * b;
  else if (op === '/') r = b !== 0 ? a / b : 'خطأ: قسمة على صفر';
  document.getElementById('result').textContent = 'الناتج: ' + r;
}
</script>
